function BookSewingCordSpoolMaker.init() BookSewingCordSpoolMaker.ironStock=12; BookSewingCordSpoolMaker.bronzeStock=10; BookSewingCordSpoolMaker.woodStock=16; BookSewingCordSpoolMaker.leatherStock=10; BookSewingCordSpoolMaker.silverStock=8; BookSewingCordSpoolMaker.goldStock=6; BookSewingCordSpoolMaker.jewelStock=4; BookSewingCordSpoolMaker.pearlStock=4; BookSewingCordSpoolMaker.productStock={}; BookSewingCordSpoolMaker.buildings={}; BookSewingCordSpoolMaker.maker=nil; BookSewingCordSpoolMaker.activeMaking={}; BookSewingCordSpoolMaker.totalProducts=0; BookSewingCordSpoolMaker.dayTimer=0; print("[BookSewingCordSpoolMaker] Royal Book Sewing Cord Spool Maker System initialized (6 products, 4 buildings)") end
function BookSewingCordSpoolMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookSewingCordSpoolMaker.maker={name=n or ("Vitičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vitičar najet: %s (spretnost: %d)",BookSewingCordSpoolMaker.maker.name,s),"success") end; return true end
function BookSewingCordSpoolMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookSewingCordSpoolMaker.build(id) local ok,e=BookSewingCordSpoolMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookSewingCordSpoolMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookSewingCordSpoolMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookSewingCordSpoolMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookSewingCordSpoolMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookSewingCordSpoolMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookSewingCordSpoolMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookSewingCordSpoolMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookSewingCordSpoolMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookSewingCordSpoolMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookSewingCordSpoolMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookSewingCordSpoolMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookSewingCordSpoolMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookSewingCordSpoolMaker.buildings==0 then return false,"Potrebna vitična delavnica" end; if not BookSewingCordSpoolMaker.maker then return false,"Potreben viticar" end; return true end
function BookSewingCordSpoolMaker.make(pt,qty) qty=qty or 1; local ok,e=BookSewingCordSpoolMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookSewingCordSpoolMaker.ironStock=BookSewingCordSpoolMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookSewingCordSpoolMaker.bronzeStock=BookSewingCordSpoolMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookSewingCordSpoolMaker.woodStock=BookSewingCordSpoolMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookSewingCordSpoolMaker.leatherStock=BookSewingCordSpoolMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookSewingCordSpoolMaker.silverStock=BookSewingCordSpoolMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookSewingCordSpoolMaker.goldStock=BookSewingCordSpoolMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookSewingCordSpoolMaker.jewelStock=BookSewingCordSpoolMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookSewingCordSpoolMaker.pearlStock=BookSewingCordSpoolMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookSewingCordSpoolMaker.maker then t=math.max(1,t-math.floor(BookSewingCordSpoolMaker.maker.skill/13)) end; table.insert(BookSewingCordSpoolMaker.activeMaking,{id="booksewingcordspool_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookSewingCordSpoolMaker.completeMaking(m) local q=1.0+(BookSewingCordSpoolMaker.getQualityBonus()/100); if BookSewingCordSpoolMaker.maker then q=q+(BookSewingCordSpoolMaker.maker.skill/140) end; q=math.min(2.5,q); BookSewingCordSpoolMaker.productStock[m.productType]=(BookSewingCordSpoolMaker.productStock[m.productType] or 0)+m.quantity; BookSewingCordSpoolMaker.totalProducts=BookSewingCordSpoolMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookSewingCordSpoolMaker.maker then BookSewingCordSpoolMaker.maker.itemsMade=BookSewingCordSpoolMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookSewingCordSpoolMaker.maker.skill=math.min(100,BookSewingCordSpoolMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vitica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"booksewingcordspool.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookSewingCordSpoolMaker.update(dt) if not _G.state then return end; BookSewingCordSpoolMaker.dayTimer=BookSewingCordSpoolMaker.dayTimer+dt; if BookSewingCordSpoolMaker.dayTimer>=30 then BookSewingCordSpoolMaker.dayTimer=0; for i=#BookSewingCordSpoolMaker.activeMaking,1,-1 do local m=BookSewingCordSpoolMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookSewingCordSpoolMaker.completeMaking(m); table.remove(BookSewingCordSpoolMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookSewingCordSpoolMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookSewingCordSpoolMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
